// HTML below is compiled from the MJML sources in ./email-templates/mjml/*.mjml (npx mjml
// <file>.mjml -o dist/<file>.html --config.minify=true --config.validationLevel=strict) with
// {{placeholder}} tokens swapped for real template-literal interpolation. Edit the .mjml source
// and recompile rather than hand-editing the HTML strings below.

// p.name comes straight from Customer.fullName (user-supplied at signup, unsanitized) — escape
// before interpolating into HTML so a name like "<img src=x onerror=...>" can't inject markup.
function escapeHtml(value: string): string {
  return value
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;")
}

// Every call site passes dates as `toISOString().slice(0, 10)`, which would otherwise reach
// the customer as "2026-03-14". All customers and deliveries are UK-based, so displayed in
// Europe/London (BST is UTC+1, never behind, so a UTC-midnight date never rolls back a day)
// and left as-is if it isn't a date we recognise — better a raw string than "Invalid Date".
export function formatDate(iso: string): string {
  const date = new Date(`${iso}T00:00:00Z`)
  if (Number.isNaN(date.getTime())) return iso
  return date
    .toLocaleDateString("en-GB", {
      weekday: "short",
      day: "numeric",
      month: "short",
      year: "numeric",
      timeZone: "Europe/London",
    })
    .replace(",", "") // "Sat, 14 Mar 2026" -> "Sat 14 Mar 2026", which reads better mid-sentence
}

